import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'

import { teamLogic } from 'scenes/teamLogic'

import { conversationsTicketsPresenceRetrieve } from '../../generated/api'
import type { TicketViewer } from './ticketPresence'

/** Matches the heartbeat cadence, so a viewer appears within one poll of opening a ticket. */
export const PRESENCE_POLL_INTERVAL_MS = 10_000

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface ticketPresenceLogicValues {
    viewersByTicketId: Record<string, TicketViewer[]>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface ticketPresenceLogicActions {
    loadViewers: (ticketIds: string[]) => {
        ticketIds: string[]
    }
    setViewers: (viewers: Record<string, TicketViewer[]>) => {
        viewers: Record<string, TicketViewer[]>
    }
}

export type ticketPresenceLogicType = MakeLogicType<ticketPresenceLogicValues, ticketPresenceLogicActions>

/** Who else has each queue ticket open. Unkeyed so every table cell reads the same map. */
export const ticketPresenceLogic = kea<ticketPresenceLogicType>([
    path(['products', 'conversations', 'frontend', 'components', 'TicketViewers', 'ticketPresenceLogic']),
    actions({
        loadViewers: (ticketIds: string[]) => ({ ticketIds }),
        setViewers: (viewers: Record<string, TicketViewer[]>) => ({ viewers }),
    }),
    reducers({
        viewersByTicketId: [
            {} as Record<string, TicketViewer[]>,
            { setViewers: (state, { viewers }) => ({ ...state, ...viewers }) },
        ],
    }),
    listeners(({ actions }) => ({
        loadViewers: async ({ ticketIds }) => {
            try {
                const { viewers = {} } = await conversationsTicketsPresenceRetrieve(
                    String(teamLogic.values.currentTeamId),
                    {
                        ticket_ids: ticketIds.join(','),
                    }
                )
                // Requested tickets with no viewers get [] so a viewer who left is cleared.
                actions.setViewers(Object.fromEntries(ticketIds.map((id) => [id, viewers[id] ?? []])))
            } catch {
                // Presence is a hint. Keep the last known viewers.
            }
        },
    })),
])
